  resizeDebounceMs: 120,   // ms — chờ sau khi đổi cỡ cửa sổ / xoay máy rồi mới tính lại bố cục (ước lượng)
  donate: {
    url: 'https://me.momo.vn/bbk9x'   // URL nhận tiền MoMo; dùng alias riêng, không dùng số điện thoại vì URL nằm trong bundle công khai
  }
};

/* ------------------------- Tự khám phá bằng dù lượn -------------------------
   Chế độ bay tự do (W/A/S/D), mô hình bay ở explore/flight.ts. Mọi số đều (ước lượng) */
const exploreBase = {
  speed: 25,           // m/s — tốc độ bay ngang không đổi (ước lượng; dù thật ≈ 10 m/s, chọn nhanh hơn để dễ chơi)
  turnRate: 0.6,       // rad/s — tốc độ đổi hướng ở góc nghiêng tối đa (ước lượng)
  bankMax: 0.45,       // rad — góc nghiêng tối đa (ước lượng)
  bankRate: 2.5,       // 1/s — tốc độ tiến tới góc nghiêng đích (ước lượng)
  climbRate: 6,        // m/s — tốc độ lên/xuống khi giữ W/S (ước lượng)
  floor: 30,           // m — độ cao tối thiểu, y thế giới (ước lượng)
  ceiling: 800,        // m — độ cao tối đa, y thế giới (ước lượng)
  takeoff: [2600, 702, -4700] as [number, number, number],   // m — điểm cất cánh [x, y, z], sườn Sơn Trà phía Bắc (ước lượng)
  takeoffYaw: Math.atan2(-1800, -2600),   // rad — hướng ban đầu về phía Thuận Phước (0, −2900) (ước lượng)
  bounds: { x0: -2600, x1: 3600, z0: -5600, z1: 2800 },   // m — khung được phép bay; ra sát mép thì bị lái vòng về (ước lượng)
  returnMargin: 400,   // m — bề rộng dải sát mép khung bắt đầu lái về tâm (ước lượng)
  chase: { back: 18, up: 6, lag: 0.25 },   // m phía sau, m phía trên, s trễ của camera bám đuôi (ước lượng)
  glider: {
    span: 11,         // m sải cánh (ước lượng)
    lines: 7,         // m khoảng treo: người treo cách cánh xuống dưới bao nhiêu mét (ước lượng)
    originAt: 0.55,   // tỉ lệ khoảng treo tính từ cánh xuống tới gốc group, không đơn vị (ước lượng)
    lineCount: 7,     // số dây treo mỗi bên, từ cánh xuống vai (ước lượng)
    chord: 2.6,       // m dây cung cánh (ước lượng)
    arch: 0.28,       // độ võng hai đầu cánh, tỉ lệ theo nửa sải (không đơn vị, ước lượng)
    segs: 16          // số đoạn cánh theo sải (ước lượng)
  }
};

export const CONFIG = {
  ...base,
  perf: perfBase,
  ui: uiBase,
  mainTotal: sum(base.mainSpans),
  thuanPhuoc: deriveTp(thuanPhuocBase),
  tranThiLy: deriveTtl(tranThiLyBase),
  songHan: deriveSh(songHanBase),
  hanTunnel: deriveHr(hanTunnelBase),
  sunWheel: deriveSunWheel(sunWheelBase),
  riverfront: riverfrontBase,
  weather: weatherBase,
  tourAll: tourAllBase,
  explore: exploreBase
};
export type SongHanConfig = typeof CONFIG.songHan;
export type HanTunnelConfig = typeof CONFIG.hanTunnel;
/* ============================ Tự khám phá: camera bám đuôi ============================
   Camera đích = pos − forward·back + up·up; trễ mũ theo CONFIG.explore.chase.lag; nhìn vào pos + forward·30. */
import * as THREE from 'three';
import { CONFIG } from '../config';
import type { GliderState } from './flight';

const K = CONFIG.explore.chase;
const _want = new THREE.Vector3();

export function exChase(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: GliderState, dt: number, snap = false): void {
  const fx = Math.cos(s.yaw), fz = -Math.sin(s.yaw);
  _want.set(s.pos.x - fx * K.back, s.pos.y + K.up, s.pos.z - fz * K.back);
  if (snap) camera.position.copy(_want);
  else camera.position.lerp(_want, 1 - Math.exp(-dt / K.lag));
  target.set(s.pos.x + fx * 30, s.pos.y, s.pos.z + fz * 30);
  camera.lookAt(target);
}
/* ============================ Tự khám phá: màn chọn phương tiện ============================
   Lớp phủ HTML (#chooser trong index.html), không thêm gì vào cảnh. Hiện sau khung đầu tiên (cảnh đã dựng phía sau)
   và chặn chuột vào canvas tới khi chọn. Chữ do data-i18n lo; ở đây chỉ khóa thẻ và gọi onPick. */

import { getLang, onChange } from '../i18n';

export type ExChoice = 'glider' | 'guided';

const el = () => document.getElementById('chooser');

/* Dù lượn cần bàn phím: thiết bị cảm ứng (không có hover) thì khóa thẻ và hiện nhãn "Chỉ dùng trên máy tính" */
function lockGliderOnTouch(root: HTMLElement): void {
  if (!window.matchMedia('(hover: none)').matches) return;
  const card = root.querySelector<HTMLButtonElement>('[data-pick="glider"]');
  if (!card) return;
  card.disabled = true;
  card.querySelector<HTMLElement>('.ex-note')?.removeAttribute('hidden');
}

/* Ô ngôn ngữ riêng của màn chọn (lớp phủ che #langSelect): chép danh sách từ #langSelect, đổi thì chuyển cho #langSelect xử lý */
function wireLang(root: HTMLElement): void {
  const mine = root.querySelector<HTMLSelectElement>('#exLang');
  const main = document.getElementById('langSelect') as HTMLSelectElement | null;
  if (!mine || !main) return;
  mine.innerHTML = main.innerHTML; mine.value = getLang();
  mine.addEventListener('change', () => { main.value = mine.value; main.dispatchEvent(new Event('change')); });
  onChange((code) => { mine.value = code; });
}

export function exShowChooser(onPick: (choice: ExChoice) => void): void {
  const root = el();
  if (!root) return;
  lockGliderOnTouch(root);
  wireLang(root);
  root.querySelectorAll<HTMLButtonElement>('button[data-pick]').forEach((b) => {
    if (b.disabled) return;
    b.addEventListener('click', () => { exHideChooser(); onPick(b.dataset.pick as ExChoice); }, { once: true });
  });
  const show = () => { root.hidden = false; root.querySelector<HTMLButtonElement>('button[data-pick]:not(:disabled)')?.focus({ preventScroll: true }); };
  const loading = document.getElementById('loading');
  if (!loading || loading.classList.contains('done')) { show(); return; }
  const mo = new MutationObserver(() => { if (loading.classList.contains('done')) { mo.disconnect(); show(); } });   // #loading.done được đặt sau khung đầu
  mo.observe(loading, { attributes: true, attributeFilter: ['class'] });
}

export function exHideChooser(): void {
  const root = el();
  if (root) root.hidden = true;
}
/* ============================ Tự khám phá: điều phối chế độ bay dù lượn ============================
   Nối flight (mô hình), glider (dù), chase (camera) với vòng animate, phím và URL.
   `?explore=glider` bay thẳng; không tham số (hoặc `?test&chooser`) hiện màn chọn; Esc tải lại trang không còn tham số explore. Camera do explore.update đặt sau updateCamera. */
import * as THREE from 'three';
import { scene, camera, controls } from '../core/renderer';
import { cam, keys } from '../views/state';
import { exCreate, exStep, exInputFromKeys, type GliderState, type GliderInput } from './flight';
import { exBuildGlider, exPlaceGlider } from './glider';
import { exChase } from './chase';
import { exShowChooser } from './chooser';

const _inp: GliderInput = { turn: 0, climb: 0 };   // đầu vào tái dùng mỗi khung

let glider: THREE.Group | null = null;
let state: GliderState | null = null;

const active = () => cam.mode === 'glider' && state !== null;

/* Một bước: mô phỏng, đặt dù, đặt camera bám */
function advance(dt: number, inp: GliderInput): void {
  exStep(state!, inp, dt);
  exPlaceGlider(glider!, state!);
  exChase(camera, controls.target, state!, dt);
}

export const explore = {
  active,
  get state() { return state; },
  get glider() { return glider; },
  start(): void {
    state = exCreate();
    if (!glider) glider = exBuildGlider();
    if (!glider.parent) scene.add(glider);
    cam.flight.then = null; cam.mode = 'glider'; controls.enabled = false;
    exPlaceGlider(glider, state);
    exChase(camera, controls.target, state, 0, true);
    document.body.classList.add('explore');
  },
  update(dt: number): void {
    if (!active()) return;
    advance(dt, exInputFromKeys(keys, _inp));
  },
  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
  step(dt: number, inp: GliderInput): void {
    if (active()) advance(dt, inp);
  },
  exit(): void {
    const u = new URL(location.href);
    u.searchParams.delete('explore'); u.searchParams.delete('chooser');
    location.replace(u.toString());
  },
};

export function setupExplore(): void {
  window.addEventListener('keydown', (e) => {
    if (!active()) return;
    if (e.key === 'Escape') { explore.exit(); return; }   // Esc thoát kể cả khi đang focus ô chọn
    const t = e.target as HTMLElement | null;
    if (t && /^(SELECT|INPUT|TEXTAREA)$/.test(t.tagName)) return;   // phím trong ô chọn/nhập không lái dù
    const k = e.key.toLowerCase(); keys.add(k);
    if (k.startsWith('arrow')) e.preventDefault();
  });
  const q = new URLSearchParams(location.search);
  if (q.has('test')) document.body.classList.add('ex-test');   // giữ HUD khi bay để test đo draw call
  document.getElementById('btnExExit')?.addEventListener('click', () => explore.exit());
  if (q.get('explore') === 'glider') { explore.start(); return; }
  if (!q.has('test') || q.has('chooser')) exShowChooser((choice) => { if (choice === 'glider') explore.start(); });   // 'guided': màn chọn tự ẩn, giao diện cũ
}
// Kiểm tra chế độ tự khám phá bằng dù lượn (kế hoạch feature/explore-du-luon).
//   Mục 1–2: mô hình bay thuần, dù, camera bám (src/explore/*) qua móc window.__app.exFlight.
//   Mục 3: điều phối chế độ bay, phím, ?explore=glider qua window.__app.explore.
//   Mục 4: màn chọn phương tiện, giao diện khi bay (body.explore), i18n 9 ngôn ngữ.
//   Mục 5: đo draw call và ms/khung ở 4 tư thế bay, ngày/đêm (chỉ đo; fail nếu phần dù ngày ≠ đêm).
//
//   npm run build && npm run test:explore
import { fileURLToPath } from 'node:url';
import { readFileSync } from 'node:fs';
import { serveDir, launch, openApp, frames, tap } from './lib.mjs';

const problems = [];
const check = (name, ok) => { if (!ok) problems.push(name); console.log(`${ok ? 'đạt ' : 'LỖI '} ${name}`); return ok; };

const srv = await serveDir(fileURLToPath(new URL('../dist/', import.meta.url)));
const browser = await launch();
try {
  // Mục 1 — mô hình bay thuần
  const P = await openApp(browser, srv.url);
  await frames(P.page, 2);
  const has = await P.page.evaluate(() => !!(window.__app && window.__app.exFlight));
  check('có __app.exFlight', has);
  if (has) {
    const r = await P.page.evaluate(() => {
      const { exCreate, exStep, exInputFromKeys, CONFIG_explore: C } = window.__app.exFlight;
      const dt = 1 / 60, out = {};
      const run = (s, inp, sec, each) => { for (let i = 0; i < Math.round(sec * 60); i++) { exStep(s, inp, dt); if (each) each(s); } };
      // 1a tốc độ ngang không đổi
      let ok = true, last = null;
      for (const [turn, climb] of [[1, 1], [-1, -1], [1, -1], [0, 0]]) {
        const s = exCreate(); last = null;
        run(s, { turn, climb }, 30, (s) => { if (last) { const v = Math.hypot(s.pos.x - last.x, s.pos.z - last.z) / dt; if (v < 24.99 || v > 25.01) ok = false; } last = { x: s.pos.x, z: s.pos.z }; });
      }
      out.a = ok;
      // 1b rẽ trái / phải
      let s = exCreate(); let y0 = s.yaw; run(s, { turn: 1, climb: 0 }, 3); out.bL = s.yaw - y0;
      s = exCreate(); y0 = s.yaw; run(s, { turn: -1, climb: 0 }, 3); out.bR = s.yaw - y0;
      // 1c lên/xuống
      s = exCreate(); run(s, { turn: 0, climb: 1 }, 200); out.cUp = s.pos.y;
      s = exCreate(); run(s, { turn: 0, climb: -1 }, 200); out.cDown = s.pos.y;
      // 1d thả phím
      s = exCreate(); run(s, { turn: 1, climb: 0 }, 2); run(s, { turn: 0, climb: 0 }, 2.5); const yb = s.yaw; run(s, { turn: 0, climb: 0 }, 0.5);
      out.dBank = s.bank; out.dYaw = s.yaw - yb;
      // 1e ranh giới khi bay thẳng
      s = exCreate(); ok = true;
      run(s, { turn: 0, climb: 0 }, 600, (s) => { if (s.pos.x < C.bounds.x0 || s.pos.x > C.bounds.x1 || s.pos.z < C.bounds.z0 || s.pos.z > C.bounds.z1) ok = false; });
      out.e = ok;
      // 1f giữ A ở góc, hướng ra ngoài
      s = exCreate(); s.pos.set(C.bounds.x1 - 50, 300, C.bounds.z0 + 50); s.yaw = Math.PI / 4; s.bank = 0; ok = true;
      let flips = 0, prev = 0;
      const t = [0];
      for (let i = 0; i < 600 * 60; i++) {
        exStep(s, { turn: 1, climb: 0 }, dt);
        if (s.pos.x < C.bounds.x0 || s.pos.x > C.bounds.x1 || s.pos.z < C.bounds.z0 || s.pos.z > C.bounds.z1) ok = false;
