import * as N from '/D:/2026 - Tuan/danang-vite/src/explore/flight';
import * as O from '/D:/2026 - Tuan/danang-vite/src/explore/flightOld';
import { CONFIG } from '/D:/2026 - Tuan/danang-vite/src/config';
const C = CONFIG.explore, b = C.bounds, dt = 1/60;
function lcg(seed:number){ return () => (seed = (seed*1664525+1013904223)>>>0)/4294967296; }
function run(M:any, s:any, inp:(i:number)=>any, sec:number){
  let clamped=0, flips=0, prev=0, longest=0, cur=0;
  for(let i=0;i<sec*60;i++){
    M.exStep(s, inp(i), dt);
    const c = s.pos.x===b.x0||s.pos.x===b.x1||s.pos.z===b.z0||s.pos.z===b.z1;
    if(c){clamped++;cur++;longest=Math.max(longest,cur);} else cur=0;
    if(i>=(sec-60)*60){const sg=Math.sign(s.bank); if(sg!==0&&prev!==0&&sg!==prev)flips++; if(sg!==0)prev=sg;}
  }
